import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"6、【訟】 坎下乾上","description":"周易口訣義 - 6、【訟】 坎下乾上","frontmatter":{"title":"6、【訟】 坎下乾上","description":"周易口訣義 - 6、【訟】 坎下乾上"},"headers":[],"relativePath":"classics/koujueyi/008.md","filePath":"classics/koujueyi/008.md"}'),r={name:"classics/koujueyi/008.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_6、【訟】-坎下乾上" tabindex="-1">6、【訟】 坎下乾上 <a class="header-anchor" href="#_6、【訟】-坎下乾上" aria-label="Permalink to “6、【訟】 坎下乾上”">​</a></h1><p>彖曰：訟，上剛下險，險而健，訟。「訟有孚窒惕，中吉」，剛來而得中也。「終兇」，訟不可成也。「利見大人」，尚中正也。「不利涉大川」，入於淵也。</p><p>象曰：天與水違行，訟。君子以作事謀始。</p><p>初六，不永所事，小有言，終吉。</p><p>象曰：「不永所事」，訟不可長也。雖「小有言」，其辯明也。</p><p>九二，不克訟，歸而逋，其邑人三百戶，無眚。</p><p>象曰：「不克訟」，歸逋竄也。自下訟上，患至掇也。</p><p>六三，食舊德，貞厲，終吉。或從王事，無成。</p><p>象曰：「食舊德」，從上吉也。</p><p>九四，不克訟，復即命渝，安貞吉。</p><p>象曰：「復即命渝」，安貞不失也。</p><p>九五，訟，元吉。</p><p>象曰：「訟元吉」，以中正也。</p><p>上九，或錫之鞶帶，終朝三禠之。</p><p>象曰：以訟受服，亦不足敬也。</p><p>解讀</p><p>「訟有孚，窒惕，中吉，終兇」者，訟者，喧競之名，乖爭之義；窒，塞也；惕，懼也。凡為訟之體，必須信實，被人止塞，若能因此而懷惕懼，於中途而止，即獲吉也。若終竟相訟，雖暫獲勝而終必有兇，故曰「終兇」也。「利見大人」者，大人能斷枉直，不失情理也。「不利涉大川」者，爭訟之時，人心乖異，涉難濟川，必見謀害，故周氏雲：「與相爭必被襲謀，當見墜於深淵也。」</p><p>象曰「天與水違行，訟，君子以作事謀始」者，天自西轉，水乃東流，二體相違，故是「訟」也。君子興為，必須謀慮其始，若初始分明，不相忤犯，訟無由生也。</p><p>「初六，不永所事，小有言，終吉」者，爭訟之體，剛先犯弱，初六既是陰柔，不敢先訟九四，九四，先訟者也。往就辯答，道理分明，不被稽留，故「不永所事」，謂不永長為爭訟之事也。</p><p>「九二，不克訟，歸而逋，其邑人三百戶，無眚」者，克，勝也；逋，逃也。九二體剛居陰，好為爭訟之事，乃與九五相爭也。以下訟上，以臣訟君，勢不可敵，爭訟如何得勝？故「不克訟」也。然訟既不勝，禍患必至，懼罪及身，遂將逃竄，竄歸小邑，可免災也；若其邑大人強，君疑不息，必被誅罰，故曰「三百戶，乃無眚」也。</p><p>「六三，食舊德，貞厲，終吉。或從王事，無成」者，六三體柔弱，順從上九，不敢有違，所有舊日之恩德，而不被黜奪，故曰「食舊德」也；然處兩剛之間，情不相得，以貞自危，故曰「貞厲」也。體柔奉上，不敢為先，但須從上九之王事，不敢先成，故曰「或從王事，無成」也。</p><p>「九四：不克訟，復即命，渝，安貞吉」者，克，勝也；即，就也；復，反也。渝，變也。四體剛而「訟」初六，初對答，道理分明，四既不勝於初六，故曰「不克訟」也。若因此不勝，而能反就初六，悔過自新，即獲安貞之吉，故曰「安貞吉」也。</p><p>九五「訟，元吉」者，餘皆不當尊位，悉是爭訟之人。九五體尊履正，即是斷訟之主。剛即無所滯溺，中即心無偏曲，處位以斯，故獲大吉，故曰「訟元吉」也。</p><p>上九：或錫之鞶帶，終朝三褫之者，以剛處上，是訟而得勝，乃受鞶帶之錫。然則不義而富，於我如浮雲，以訟受榮，如何可保？故終一朝間，三被褫脫，不足敬也。因訟至錫，非德而受，故不足敬。旦至食時為朝。馬雲：「鞶帶，大帶衣也。」</p>',24)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
